import{_ as r,C as s,o,c as n,a6 as t,E as i}from"./chunks/framework.CA8SQds3.js";const h="/screenshots/server-coverage.png",f=JSON.parse('{"title":"Server coverage","description":"The backend files, functions and lines each Playwright test ran, recorded per test from an ASP.NET Core build instrumented for coverage, even when the tests run in parallel against one backend.","frontmatter":{"title":"Server coverage","description":"The backend files, functions and lines each Playwright test ran, recorded per test from an ASP.NET Core build instrumented for coverage, even when the tests run in parallel against one backend.","lang":"en-US","head":[["link",{"rel":"canonical","href":"https://piwitests.dev/features/server-coverage.html"}],["meta",{"property":"og:url","content":"https://piwitests.dev/features/server-coverage.html"}],["meta",{"property":"og:title","content":"Server coverage | Piwi Dashboard"}],["meta",{"property":"og:description","content":"The backend files, functions and lines each Playwright test ran, recorded per test from an ASP.NET Core build instrumented for coverage, even when the tests run in parallel against one backend."}]]},"headers":[],"relativePath":"features/server-coverage.md","filePath":"features/server-coverage.md","lastUpdated":1792619403000}'),d={name:"features/server-coverage.md"};function l(c,e,u,p,g,m){const a=s("DemoExamples");return o(),n("div",null,[e[0]||(e[0]=t('<h1 id="server-coverage" tabindex="-1">Server coverage <a class="header-anchor" href="#server-coverage" aria-label="Permalink to &quot;Server coverage&quot;">​</a></h1><p>With an ASP.NET Core backend built for coverage, each test records the backend code it ran: its files, the functions that ran in them and, at the finest granularity, the executed lines. Requests are told apart, so tests running in parallel against one shared backend each keep their own. The browser side is <a href="./code-reach.html">code reach</a>; both feed the <a href="./code-reach.html#on-the-execution-page">execution page</a>, the <a href="./code-reach.html#which-tests-run-a-file">file coverage page</a>, the <a href="./editor-coverage.html">editors</a> and the <a href="./coverage-insights.html">coverage insights</a>.</p><h2 id="turn-it-on" tabindex="-1">Turn it on <a class="header-anchor" href="#turn-it-on" aria-label="Permalink to &quot;Turn it on&quot;">​</a></h2><ol><li>Add the <code>PiwiTests.Instrumentation.Coverage</code> package to every project whose code you want covered, as its <a href="https://github.com/PiwiTests/platform/tree/main/integrations/aspnetcore/PiwiTests.Instrumentation.Coverage#readme" target="_blank" rel="noreferrer">README</a> shows, serve it with <code>app.UsePiwiTestLogs()</code> (<a href="/guide/backend-logs.html">backend instrumentation</a>), and build the test environment with <code>-p:PiwiCoverage=true</code>. Never ship that build to production: its code runs slower, and its coverage endpoints expose source paths and line numbers. It refuses to start in the Production environment, and <code>PiwiCoverageForbidden</code> makes a build fail when coverage reaches it (<a href="https://github.com/PiwiTests/platform/tree/main/integrations/aspnetcore/PiwiTests.Instrumentation.Coverage#enabling-it" target="_blank" rel="noreferrer">README</a>).</li><li>Set the reporter&#39;s <code>coverage.server</code> option, or <code>PIWI_COVERAGE_SERVER</code>, with the <a href="/guide/capture-fixtures.html">capture fixtures</a> in place.</li></ol><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">reporter</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [[</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;@piwitests/reporter&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, { coverage: { server: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;lines&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> } }]],</span></span></code></pre></div><p>Against a backend that is not a coverage build, no response names any coverage, so the reporter collects nothing and the option costs nothing: it can stay on, and the build decides.</p><h2 id="what-it-records" tabindex="-1">What it records <a class="header-anchor" href="#what-it-records" aria-label="Permalink to &quot;What it records&quot;">​</a></h2><table tabindex="0"><thead><tr><th><code>coverage.server</code></th><th>Records per test</th></tr></thead><tbody><tr><td><code>files</code></td><td>the backend files that ran, paths only</td></tr><tr><td><code>functions</code></td><td>also the start and end line of each function that ran</td></tr><tr><td><code>lines</code></td><td>also the executed lines</td></tr></tbody></table><p>With <code>functions</code> and <code>lines</code>, each file names the git blob its line numbers refer to. At the end of the run the reporter also sends each backend&#39;s run-level coverage, attributed to no test, with each file&#39;s executable lines at <code>lines</code>: the lines no test runs, in every assembly built with coverage, including those whose code never ran. A test whose coverage the backend no longer held, or that could not be collected, is marked incomplete.</p><figure><img src="'+h+'" alt="The backend files one test ran, recorded by line"><figcaption>One test&#39;s backend files, with the lines it ran.</figcaption></figure><p>The backend names the checksum of the source each file was compiled from. When the file in the reporter&#39;s checkout differs (the backend was built from another commit), the reporter keeps the file&#39;s path but drops its line numbers, which would point at the wrong lines, and marks the test incomplete; the run-level coverage drops them the same way.</p><h2 id="how-it-is-collected" tabindex="-1">How it is collected <a class="header-anchor" href="#how-it-is-collected" aria-label="Permalink to &quot;How it is collected&quot;">​</a></h2><p>Each response names its request&#39;s coverage in an <code>X-Piwi-Coverage</code> header. Once the test ends, outside its time, the reporter asks each backend origin for the coverage its pages and API calls named, several tests per call. The run-level coverage is read as the run&#39;s last test ends, while a Playwright <code>webServer</code> is still up, and the lines and functions the tests&#39; coverage named are added to it. Every answer names the backend process: a random id, which also starts each request id, and when the process started. The run-level coverage is whole only when the process that answers it is the one that served the run&#39;s first requests.</p><h2 id="limits" tabindex="-1">Limits <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Limits&quot;">​</a></h2><ul><li><strong>Run level only:</strong> lambdas created at startup (inline minimal API handlers, inline middleware, DI factory lambdas), work outside a request (hosted services, timers), and work a request started that still runs once the reporter collected its coverage. The methods they call count normally.</li><li><strong>API calls</strong> through Playwright&#39;s <code>request</code> fixture keep their last response&#39;s coverage only: a redirect&#39;s earlier responses, and a response <code>failOnStatusCode</code> turns into an error, name none.</li><li><strong>One backend per request:</strong> a call the backend makes to another counts there only if it forwards the <code>X-Piwi-Coverage</code> header.</li><li><strong>A restart during the run:</strong> the new process starts with no coverage. Each test&#39;s lines are kept, from its own coverage; what the earlier process ran outside a request (startup, background work) is lost, and a test whose requests it served but the reporter had not yet collected is marked incomplete. The reporter warns, the run&#39;s header reads <em>Coverage incomplete: the backend restarted during the run</em>, and the run&#39;s coverage in the <a href="https://piwitests.dev/demo/docs" target="_blank" rel="noreferrer">API</a> names the origin and about when it restarted. A backend unreachable at the end of the run is flagged the same way, with only the tests&#39; lines kept. The commit&#39;s <a href="./combined-coverage.html">combined coverage</a> notes the run, and its <code>e2e</code> suite reads as incomplete unless a complete run of the commit counts beside it.</li><li><strong>Exclusions:</strong> the coverage build leaves out what coverlet does, read from the project&#39;s coverlet settings (<a href="https://github.com/PiwiTests/platform/tree/main/integrations/aspnetcore/PiwiTests.Instrumentation.Coverage#what-it-leaves-out" target="_blank" rel="noreferrer">README</a>): an excluded member has no executable lines and no coverage.</li><li>C# and Visual Basic only.</li></ul><h2 id="cost" tabindex="-1">Cost <a class="header-anchor" href="#cost" aria-label="Permalink to &quot;Cost&quot;">​</a></h2><p>On a large ASP.NET Core and Vue application, the coverage build alone ran within 1% of a normal build, and per-test line coverage added under 10% to its UI tests, with no measurable change in its CPU. The build records the same way at every granularity, so files and functions cost what lines cost. <a href="/reference/coverage-cost.html">Coverage cost</a> has every mode, how it was measured, and the prototype figures.</p><h2 id="try-it-in-the-demo" tabindex="-1">Try it in the demo <a class="header-anchor" href="#try-it-in-the-demo" aria-label="Permalink to &quot;Try it in the demo&quot;">​</a></h2>',18)),i(a),e[1]||(e[1]=t('<h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./code-reach.html">Code reach</a>: the browser side, and where the coverage is read</li><li><a href="./editor-coverage.html">Coverage in the editor</a>: the lines tests ran, in VS Code and the JetBrains IDEs</li><li><a href="/guide/backend-logs.html">Backend instrumentation</a>: the middleware that serves the coverage</li><li><a href="/reference/coverage-cost.html">Coverage cost</a>: what each mode costs</li></ul>',2))])}const b=r(d,[["render",l]]);export{f as __pageData,b as default};
